[CmdletBinding()]
param([Parameter(Mandatory=$true)][string]$ExePath,[int]$Iterations=50,[int]$WarmupSeconds=3,[int]$ExitTimeoutSeconds=5,[string]$OutputDir=(Join-Path $PSScriptRoot 'v9-lifecycle-results'),[switch]$NoF2,[switch]$NoDisplayChange)
Set-StrictMode -Version Latest;$ErrorActionPreference='Stop';if(!(Test-Path -LiteralPath $ExePath -PathType Leaf)){throw "Executable not found: $ExePath"};$ExePath=(Resolve-Path -LiteralPath $ExePath).Path;New-Item -ItemType Directory -Force $OutputDir|Out-Null;$stamp=Get-Date -Format 'yyyyMMdd-HHmmss';$csv=Join-Path $OutputDir "v9-lifecycle-$stamp.csv";$json=Join-Path $OutputDir "v9-lifecycle-$stamp-summary.json"
Add-Type @"
using System; using System.Runtime.InteropServices; public static class V9LifeNative {[DllImport("user32.dll")] public static extern bool PostMessage(IntPtr h,uint m,IntPtr w,IntPtr l);[DllImport("user32.dll")] public static extern int GetSystemMetrics(int i);}
"@
$C=0x10;$D=0x7e;$KD=0x100;$KU=0x101;$F2=0x71
function Wait-Hwnd($p){$d=(Get-Date).AddSeconds(12);while((Get-Date) -lt $d){$p.Refresh();if($p.HasExited){return [IntPtr]::Zero};if($p.MainWindowHandle -ne [IntPtr]::Zero){return $p.MainWindowHandle};Start-Sleep -Milliseconds 100};[IntPtr]::Zero}
function K($h){[void][V9LifeNative]::PostMessage($h,$KD,[IntPtr]$F2,[IntPtr]::Zero);Start-Sleep -Milliseconds 60;[void][V9LifeNative]::PostMessage($h,$KU,[IntPtr]$F2,[IntPtr](1 -shl 31))}
function DC($h){$w=[V9LifeNative]::GetSystemMetrics(0);$hh=[V9LifeNative]::GetSystemMetrics(1);$lp=(($hh -band 0xffff) -shl 16) -bor ($w -band 0xffff);[void][V9LifeNative]::PostMessage($h,$D,[IntPtr]32,[IntPtr]$lp)}
function M($t,$pat){$m=[regex]::Match($t,$pat,'IgnoreCase');if($m.Success){$m.Groups[1].Value}else{$null}}
$rows=@();$bad=0;$forced=0
for($i=1;$i -le $Iterations;$i++){$res='PASS';$why='';$p=$null;$s=$null;$title='';$exit=$null;$didForce=$false;try{$p=Start-Process -FilePath $ExePath -PassThru;$h=Wait-Hwnd $p;if($h -eq [IntPtr]::Zero){throw 'main window not ready'};Start-Sleep -Seconds $WarmupSeconds;$p.Refresh();if($p.HasExited){throw 'exited during warmup'};if(!$NoDisplayChange){DC $h;Start-Sleep -Milliseconds 600};if(!$NoF2){K $h;Start-Sleep -Milliseconds 450;K $h;Start-Sleep -Milliseconds 700};$p.Refresh();$title=$p.MainWindowTitle;$rec=[regex]::Match($title,'\brec\s*[=: ]\s*(\d+)\s*/\s*(\d+)','IgnoreCase');$s=[pscustomobject]@{thread=M $title '\bthread\s*[=: ]\s*(OK|ALIVE|DEAD)';excl=M $title '\bexcl\s*[=: ]\s*(YES|NO)';shot=M $title '\bshot\s*[=: ]\s*(ON|OFF)';af=M $title '\bafail\s*[=: ]\s*(\d+)';bt=M $title '\bbtimeout\s*[=: ]\s*(\d+)';dev=M $title '\bdevrem\s*[=: ]\s*(\d+)';rf=if($rec.Success){$rec.Groups[2].Value}else{$null}};if($s.thread -eq 'DEAD'){throw 'thread=DEAD'};foreach($x in @('af','bt','dev','rf')){if($s.$x -ne $null -and [long]$s.$x -gt 0){throw "$x=$($s.$x)"}};if($s.excl -and $s.excl -ne 'YES'){throw "excl=$($s.excl)"};if($s.shot -and $s.shot -ne 'OFF'){throw "shot=$($s.shot)"};[void][V9LifeNative]::PostMessage($h,$C,[IntPtr]::Zero,[IntPtr]::Zero);if(!$p.WaitForExit($ExitTimeoutSeconds*1000)){$didForce=$true;$forced++;throw 'WM_CLOSE timeout'};$exit=$p.ExitCode;if($exit -ne 0){throw "exit=$exit"}}catch{$res='FAIL';$why=$_.Exception.Message;$bad++;if($p){try{$p.Refresh()}catch{};if(!$p.HasExited){if(!$didForce){$forced++;$didForce=$true};Stop-Process -Id ([int]$p.Id) -Force -ErrorAction SilentlyContinue}}};$rows+=[pscustomobject]@{iteration=$i;result=$res;reason=$why;pid=if($p){$p.Id}else{$null};exit=$exit;forced=$didForce;thread=if($s){$s.thread}else{$null};excl=if($s){$s.excl}else{$null};shot=if($s){$s.shot}else{$null};title=$title};$rows|Export-Csv $csv -NoTypeInformation -Encoding UTF8;Write-Host "[$i/$Iterations] $res $why"}
$status=if($bad -eq 0 -and $forced -eq 0){'PASS'}else{'FAIL'};[ordered]@{status=$status;exe=$ExePath;iterations=$Iterations;passed=$Iterations-$bad;failed=$bad;forcedCleanups=$forced;csv=$csv}|ConvertTo-Json|Set-Content $json -Encoding UTF8;Write-Host "V9 lifecycle: $status";Write-Host "CSV: $csv";Write-Host "Summary: $json";if($status -eq 'FAIL'){exit 2}
